public static function roundHalfUpTo6(string $value): string
{
    // value×10⁶ — целая часть в микронах; +0.5 и обрезаем (HALF_UP, знак «+»)
    return bcdiv(bcadd(bcmul($value, self::DIVISOR_1M, 0), '0.5', 0), self::DIVISOR_1M, 6);
}

